/// <summary>
/// Reason + comment dialog for Dispute, Suspend and Refuse. Comment is mandatory for Suspend and
/// Refuse, optional for Dispute (Clear France API v4.1 - 6.5). The reason list is filtered to the
/// action and is not editable here - reason codes are a contract with the tax authority.
/// </summary>
[Form]
public class CELTLifecycleActionDialog extends FormRun
{
    CELTLifecycleAction action;
    str                 selectedReason;
    str                 selectedComment;
}

public void init()
{
    super();

    if (element.args() && element.args().parmEnumType() == enumNum(CELTLifecycleAction))
    {
        action = element.args().parmEnum();
    }

    element.design().caption(strFmt("@CELTLabels:LcDialogCaption", enum2Str(action)));

    // 6.5: comment mandatory for Suspend and Refuse, optional for Dispute.
    CommentCtrl.mandatory(action == CELTLifecycleAction::Suspend || action == CELTLifecycleAction::Refuse);
}

/// <summary>
/// Validates and closes. Blocking happens before anything is sent; a failed validation keeps
/// the dialog open so nothing typed is lost.
/// </summary>
public void okClicked()
{
    str reason  = ReasonCodeCtrl.text();
    str comment = CommentCtrl.text();

    if (reason == '')
    {
        warning("@CELTLabels:LcReasonMandatory");
        return;
    }

    if (!CELTLifecycleReasonCode::exist(action, reason))
    {
        warning(strFmt("@CELTLabels:LcReasonUnknown", reason));
        return;
    }

    if (comment == '' && (action == CELTLifecycleAction::Suspend || action == CELTLifecycleAction::Refuse))
    {
        warning("@CELTLabels:LcCommentMandatory");
        return;
    }

    selectedReason  = reason;
    selectedComment = comment;

    element.closeOk();
}

/// <summary>
/// Reason codes of the current action only.
/// </summary>
public void lookup()
{
    SysTableLookup       tableLookup = SysTableLookup::newParameters(tableNum(CELTLifecycleReasonCode), this);
    Query                query       = new Query();
    QueryBuildDataSource qbds        = query.addDataSource(tableNum(CELTLifecycleReasonCode));

    qbds.addRange(fieldNum(CELTLifecycleReasonCode, Action)).value(queryValue(element.parmAction()));

    tableLookup.addLookupfield(fieldNum(CELTLifecycleReasonCode, ReasonCode), true);
    tableLookup.addLookupfield(fieldNum(CELTLifecycleReasonCode, Description));
    tableLookup.parmQuery(query);
    tableLookup.performFormLookup();
}
